import{c as a,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const r="/assets/zh-cn_image_0000001487383566.D93MYiE3.png",o="/assets/zh-cn_image_0000001538104137.BzNhofeH.png",m=JSON.parse('{"title":"Sort32","description":"","frontmatter":{},"headers":[{"level":1,"title":"Sort32","slug":"sort32"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/Sort32.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/Sort32.md"}'),n={name:"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/Sort32.md"};function d(i,t,c,p,h,u){return e(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="sort32" tabindex="-1">Sort32 <a class="header-anchor" href="#sort32" aria-label="Permalink to &quot;Sort32&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>排序函数，一次迭代可以完成32个数的排序，数据需要按如下描述结构进行保存：</p><p>score和index分别存储在src0和src1中，按score进行排序（score大的排前面），排序好的score与其对应的index一起以（score, index）的结构存储在dst中。不论score为half还是float类型，dst中的（score, index）结构总是占据8Bytes空间。</p><p>如下所示：</p><ul><li><p>当score为float，index为uint32_t类型时，计算结果中index存储在高4Bytes，score存储在低4Bytes。</p><p><img src="'+r+'" alt=""></p></li><li><p>当score为half，index为uint32_t类型时，计算结果中index存储在高4Bytes，score存储在低2Bytes， 中间的2Bytes保留。</p><p><img src="'+o+`" alt=""></p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Sort32(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;uint32_t&gt;&amp; src1, const int32_t repeatTime)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 此源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>src1</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 此源操作数固定为uint32_t数据类型。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数，int32_t类型，每次迭代完成32个元素的排序，下次迭代src0和src1各跳过32个elements，dst跳过32*8 Byte空间。取值范围：repeatTime∈[0,255]。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>当存在score[i]与score[j]相同时，如果i&gt;j，则score[j]将首先被选出来，排在前面。</li><li>每次迭代内的数据会进行排序，不同迭代间的数据不会进行排序。</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整使用样例请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/mrg_sort" target="_blank" rel="noreferrer">MrgSort样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; srcLocal0 = inQueueSrc0.DeQue&lt;float&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;uint32_t&gt; srcLocal1 = inQueueSrc1.DeQue&lt;uint32_t&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dstLocal = outQueueDst.AllocTensor&lt;float&gt;();</span></span>
<span class="line"><span>// repeatTime = 4, 对128个数分成4组进行排序，每次完成1组32个数的排序</span></span>
<span class="line"><span>AscendC::Sort32&lt;float&gt;(dstLocal, srcLocal0, srcLocal1, 4);</span></span>
<span class="line"><span>outQueueDst.EnQue&lt;float&gt;(dstLocal);</span></span>
<span class="line"><span>inQueueSrc0.FreeTensor(srcLocal0);</span></span>
<span class="line"><span>inQueueSrc1.FreeTensor(srcLocal1);</span></span></code></pre></div>`,22)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
